#include <stdio.h>
#include <linux/ppdev.h>
#include <linux/parport.h>

int main() {
    printf("# Code generated by syz-sysgen. DO NOT EDIT.\n");
    printf("arches = 386, amd64\n");

    // Ioctl numbers
    printf("PPCLAIM = %u\n", PPCLAIM);
    printf("PPCLRIRQ = %u\n", PPCLRIRQ);
    printf("PPDATADIR = %u\n", PPDATADIR);
    printf("PPEXCL = %u\n", PPEXCL);
    printf("PPFCONTROL = %u\n", PPFCONTROL);
    printf("PPGETFLAGS = %u\n", PPGETFLAGS);
    printf("PPGETMODE = %u\n", PPGETMODE);
    printf("PPGETMODES = %u\n", PPGETMODES);
    printf("PPGETPHASE = %u\n", PPGETPHASE);
    printf("PPGETTIME = %u\n", PPGETTIME);
    printf("PPNEGOT = %u\n", PPNEGOT);
    printf("PPRCONTROL = %u\n", PPRCONTROL);
    printf("PPRDATA = %u\n", PPRDATA);
    printf("PPRELEASE = %u\n", PPRELEASE);
    printf("PPRSTATUS = %u\n", PPRSTATUS);
    printf("PPSETFLAGS = %u\n", PPSETFLAGS);
    printf("PPSETMODE = %u\n", PPSETMODE);
    printf("PPSETPHASE = %u\n", PPSETPHASE);
    printf("PPSETTIME = %u\n", PPSETTIME);
    printf("PPWCONTROL = %u\n", PPWCONTROL);
    printf("PPWCTLONIRQ = %u\n", PPWCTLONIRQ);
    printf("PPWDATA = %u\n", PPWDATA);
    printf("PPYIELD = %u\n", PPYIELD);

    // IEEE1284 modes
    printf("IEEE1284_ADDR = %u\n", IEEE1284_ADDR);
    printf("IEEE1284_DATA = %u\n", IEEE1284_DATA);
    printf("IEEE1284_DEVICEID = %u\n", IEEE1284_DEVICEID);
    printf("IEEE1284_EXT_LINK = %u\n", IEEE1284_EXT_LINK);
    printf("IEEE1284_MODE_BECP = %u\n", IEEE1284_MODE_BECP);
    printf("IEEE1284_MODE_BYTE = %u\n", IEEE1284_MODE_BYTE);
    printf("IEEE1284_MODE_COMPAT = %u\n", IEEE1284_MODE_COMPAT);
    printf("IEEE1284_MODE_ECP = %u\n", IEEE1284_MODE_ECP);
    printf("IEEE1284_MODE_ECPRLE = %u\n", IEEE1284_MODE_ECPRLE);
    printf("IEEE1284_MODE_ECPSWE = %u\n", IEEE1284_MODE_ECPSWE);
    printf("IEEE1284_MODE_EPP = %u\n", IEEE1284_MODE_EPP);
    printf("IEEE1284_MODE_EPPSL = %u\n", IEEE1284_MODE_EPPSL);
    printf("IEEE1284_MODE_EPPSWE = %u\n", IEEE1284_MODE_EPPSWE);
    printf("IEEE1284_MODE_NIBBLE = %u\n", IEEE1284_MODE_NIBBLE);

    // Parport control flags
    printf("PARPORT_CONTROL_AUTOFD = %u\n", PARPORT_CONTROL_AUTOFD);
    printf("PARPORT_CONTROL_INIT = %u\n", PARPORT_CONTROL_INIT);
    printf("PARPORT_CONTROL_SELECT = %u\n", PARPORT_CONTROL_SELECT);
    printf("PARPORT_CONTROL_STROBE = %u\n", PARPORT_CONTROL_STROBE);

    // PPDEV flags
    printf("PP_FASTREAD = %u\n", PP_FASTREAD);
    printf("PP_FASTWRITE = %u\n", PP_FASTWRITE);
    printf("PP_FLAGMASK = %u\n", PP_FLAGMASK);
    printf("PP_W91284PIC = %u\n", PP_W91284PIC);

    return 0;
}
EOF
